window.kbPageData["views/entry/k-e07591671f29d414"] = {"key":"entry/k-e07591671f29d414","state":{"route":"entry/k-e07591671f29d414"},"node":{"id":"k-e07591671f29d414","mode":"k","title":"不期而遇与心心相印","type":"概念与词义","domain":"汉语","reading":"","intro":"","priority":100,"aliases":["不期而遇与心心相印的词义区别","“不期而遇”与“心心相印”的词义及适用对象"],"qs":["江苏 2025 A类 行测#43","江苏 2025 B类 行测#44","江苏 2025 C类 行测#44"],"current":false,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"repeatPositions":2,"reviewSet":"多题条目","independentCount":1,"directorySummary":"不期而遇指没有事先约定而意外相遇。心心相印形容彼此心意相通。","review":{"title":"不期而遇与心心相印","type":"概念与词义","definition":"不期而遇指没有事先约定而意外相遇。心心相印形容彼此心意相通。","explanation":"不期而遇可以从人与人的偶遇引申到人与事物的偶然接触。心心相印用于能够彼此理解心意的人或群体，强调双方的默契。","basis":"据关联原题及所列出处编释。","references":[{"source":"词典不期而遇","location":"“不期而遇”词目"},{"source":"词典心心相印","location":"“心心相印”词目"}],"related":[],"examFocus":{"江苏 2025 A类 行测#43":"结合微博留言和教材换图的例子，辨析第二空的成语能否描述公众与探月成果的关系，并留意第三空与“共识”的搭配。"}},"readings":[{"origin":"k-e07591671f29d414","title":"不期而遇与心心相印","qs":["江苏 2025 A类 行测#43","江苏 2025 B类 行测#44"],"definition":"不期而遇指没有事先约定而意外相遇。心心相印形容彼此心意相通。","explanation":"不期而遇可以从人与人的偶遇引申到人与事物的偶然接触。心心相印用于能够彼此理解心意的人或群体，强调双方的默契。","evidence":"","doubt":"","references":[{"source":"词典不期而遇","location":"“不期而遇”词目"},{"source":"词典心心相印","location":"“心心相印”词目"}]},{"origin":"k-f3e8620038663ffc","title":"不期而遇与心心相印","qs":["江苏 2025 C类 行测#44"],"definition":"“不期而遇”指未经约定而意外相遇，可引申为偶然接触。“心心相印”形容双方心意相通。","explanation":"微博上的玉兔和教材里的中国月面图，都是公众在日常生活中接触探月工程的途径。第二空写公众与探月成果的相遇，用“不期而遇”贴切。“成果”“侧面”无法与公众形成“心心相印”所要求的双方心意相通的关系。","evidence":"越来越多的人与探月工程的某项成果、某个侧面","doubt":"","references":[]}],"aspects":[{"title":"偶然接触与心意相通的适用对象","uses":[{"unit":"Q1","role":"直接考查","use":"文段借社交媒体和新版教材等例子写公众在日常生活中接触探月成果。第二空的对象是探月工程的成果或侧面，选C项“不期而遇”。","evidence":"越来越多的人与探月工程的某项成果、某个侧面","qids":["江苏 2025 A类 行测#43","江苏 2025 B类 行测#44"]}]}]},"questions":{"江苏 2025 A类 行测#43":{"paper":"江苏 2025 A类 行测","n":43,"mod":"言语理解与表达","src":["98687766ac277f427cd6.pdf",9],"asrc":["4fe8e0544dd7b47699d2.pdf",14],"card":"04b2d2806e5f4ef5d3e6e6f2","links":[{"id":"k-e07591671f29d414","role":"直接考查","why":"“不期而遇”可形容公众偶然接触探月成果，“心心相印”形容彼此心意一致，需要能够相互理解的主体。"}]},"江苏 2025 B类 行测#44":{"paper":"江苏 2025 B类 行测","n":44,"mod":"言语理解与表达","src":["91e0d9fd02ca7ec6d61f.pdf",9],"asrc":["f2ff67a0f2a2f7e8e926.pdf",15],"card":"5be42988843be8399307b8ec","links":[{"id":"k-e07591671f29d414","role":"直接考查","why":"不期而遇可比喻偶然接触某项成果，心心相印描述彼此心意一致。第二空需要表达人与成果的接触。"}]},"江苏 2025 C类 行测#44":{"paper":"江苏 2025 C类 行测","n":44,"mod":"言语理解与表达","src":["ffc394a1c160f331ec57.pdf",10],"asrc":["d1de3b437151c05b769e.pdf",13],"card":"384f4fea4a804bb9607f615b","links":[{"id":"k-e07591671f29d414","role":"直接考查","why":"“不期而遇”可描述人与探月成果的偶然接触，“心心相印”用于彼此心意相通的双方。"}]}},"terms":{},"references":{"词典不期而遇":{"name":"《重編國語辭典修訂本》· 不期而遇","url":"https://dict.revised.moe.edu.tw/dictView.jsp?ID=21026"},"词典心心相印":{"name":"《重編國語辭典修訂本》· 心心相印","url":"https://dict.revised.moe.edu.tw/dictView.jsp?ID=108840"}},"topics":[],"units":{"k-e07591671f29d414":[["江苏 2025 A类 行测#43","江苏 2025 B类 行测#44","江苏 2025 C类 行测#44"]]}};
